code.js:
const AISLES = { milk: "Dairy", eggs: "Dairy", cheese: "Dairy", bread: "Bakery", apples: "Fruit and vegetables" };
const status = document.getElementById("status");
let state;
const groupOf = () => "";
const row = (item) => {
  const li = document.createElement("li");
  li.dataset.hook = "item";
  const box = document.createElement("input");
  box.type = "checkbox";
  box.id = "got-" + item.id;
  box.checked = item.done === true;
  box.addEventListener("change", () =>
    save([{ op: "replace", collection: "items", id: item.id, revisionCount: state.revisions.items[item.id], fields: { done: box.checked } }], box.checked ? item.title + " is ticked off." : item.title + " is back on the list."),
  );
  const label = document.createElement("label");
  label.htmlFor = box.id;
  label.textContent = item.title;
  if (item.done) label.className = "done";
  const remove = document.createElement("button");
  remove.type = "button";
  remove.dataset.hook = "item-remove";
  remove.textContent = "Remove " + item.title;
  remove.addEventListener("click", () =>
    save([{ op: "remove", collection: "items", id: item.id, revisionCount: state.revisions.items[item.id] }], item.title + " is off the list."),
  );
  li.append(box, label, remove);
  return li;
};
const render = () => {
  const groups = new Map();
  for (const item of state.data.items) {
    const group = groupOf(item);
    if (!groups.has(group)) groups.set(group, []);
    groups.get(group).push(item);
  }
  document.getElementById("list").replaceChildren(...[...groups].flatMap(([group, items]) => {
    const list = document.createElement("ul");
    list.setAttribute("aria-label", group || "Items");
    list.append(...items.map(row));
    if (!group) return [list];
    const heading = document.createElement("h3");
    heading.textContent = group;
    return [heading, list];
  }));
};
const load = () => tessera.call("data.read").then((read) => { state = read; render(); });
const save = (operations, said) =>
  tessera.call("data.patch", { operations }).then(load).then(
    () => { status.textContent = said; },
    () => { status.textContent = "That wasn't saved. Try again."; return load(); },
  );
load();
document.querySelector("[data-hook=item-add]").addEventListener("click", () => {
  const field = document.querySelector("[data-hook=item-name]");
  const title = field.value.trim();
  if (!title) { status.textContent = "Write what to buy first."; return; }
  field.value = "";
  save([{ op: "add", collection: "items", record: { title } }], title + " is on the list.");
});
